window.__TNPSC_REGISTER_TEST__("tamil", 7, [{"id":601,"subject":"tamil","testNumber":7,"question":"தமிழின் முதல் காப்பியமாகப் போற்றப்படும் 'சிலப்பதிகாரம்' என்னும் நூலை இயற்றியவர் யார்?","options":["சீத்தலைச் சாத்தனார்","இளங்கோவடிகள்","திருத்தக்கதேவர்","கம்பர்"],"correctAnswer":1,"explanation":"சிலப்பதிகாரத்தை இயற்றியவர் சேர மரபைச் சேர்ந்த இளங்கோவடிகள் ஆவார். இவர் சேரன் செங்குட்டுவனின் தம்பியாவார். இயல், இசை, நாடகம் ஆகிய முத்தமிழும் இணைந்துள்ளதால் இது தமிழின் முதல் காப்பியமாகவும் முத்தமிழ்க் காப்பியமாகவும் போற்றப்படுகிறது.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":602,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரம் உணர்த்தும் முப்பெரும் உண்மைகளில் பொருந்தாத கூற்று எது?","options":["அரசியல் பிழைத்தோர்க்கு அறம் கூற்றாகும்","உரைசால் பத்தினியை உயர்ந்தோர் ஏத்துவர்","ஊழ்வினை உருத்து வந்து ஊட்டும்","யாதும் ஊரே யாவரும் கேளிர்"],"correctAnswer":3,"explanation":"சிலப்பதிகாரப் பதிகம் 'அரசியல் பிழைத்தோர்க்கு அறம் கூற்றாகும்', 'உரைசால் பத்தினியை உயர்ந்தோர் ஏத்துவர்', 'ஊழ்வினை உருத்து வந்து ஊட்டும்' ஆகிய முப்பெரும் உண்மைகளை உணர்த்துகிறது. 'யாதும் ஊரே யாவரும் கேளிர்' என்பது புறநானூற்றில் கணியன் பூங்குன்றனார் பாடிய வரியாகும்.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":603,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் அமைந்துள்ள மூன்று காண்டங்கள் மற்றும் அவற்றின் காதை எண்ணிக்கைகளின் சரியான வரிசை எது?","options":["புகார்க்காண்டம் (10), மதுரைக்காண்டம் (13), வஞ்சிக்காண்டம் (7)","புகார்க்காண்டம் (13), மதுரைக்காண்டம் (10), வஞ்சிக்காண்டம் (7)","புகார்க்காண்டம் (10), மதுரைக்காண்டம் (10), வஞ்சிக்காண்டம் (10)","புகார்க்காண்டம் (7), மதுரைக்காண்டம் (13), வஞ்சிக்காண்டம் (10)"],"correctAnswer":0,"explanation":"சிலப்பதிகாரம் மொத்தம் 3 காண்டங்களையும் 30 காதைகளையும் கொண்டது. அவற்றுள் புகார்க்காண்டம் 10 காதைகளையும், மதுரைக்காண்டம் 13 காதைகளையும், வஞ்சிக்காண்டம் 7 காதைகளையும் கொண்டுள்ளன.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":604,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தைக் 'குடிமக்கள் காப்பியம்' என்று சிறப்பித்துக் கூறிய தமிழ் அறிஞர் யார்?","options":["உ.வே.சாமிநாதையர்","வ.உ.சிதம்பரனார்","தெ.பொ.மீனாட்சிசுந்தரனார்","மறைமலையடிகள்"],"correctAnswer":2,"explanation":"மன்னர்களைப் போற்றாமல் வணிகக் குடியில் பிறந்த கோவலனையும் கண்ணகியையும் காப்பியத் தலைவனாகவும் தலைவியாகவும் படைத்ததால், சிலப்பதிகாரத்தைத் 'குடிமக்கள் காப்பியம்' எனத் தெ.பொ.மீனாட்சிசுந்தரனார் சிறப்பித்தார்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":605,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தின் முதல் காதையும் இறுதிக் காதையும் முறையே எவை?","options":["மனையறம் படுத்த காதை, நடுகற் காதை","மங்கல வாழ்த்துப் பாடல், வரந்தரு காதை","அரங்கேற்று காதை, வாழ்த்துக் காதை","இந்திரவிழா ஊரெடுத்த காதை, காட்சிக் காதை"],"correctAnswer":1,"explanation":"சிலப்பதிகாரத்தின் புகார்க்காண்டத்தில் உள்ள முதல் காதை 'மங்கல வாழ்த்துப் பாடல்' ஆகும். வஞ்சிக்காண்டத்தின் நிறைவாக அமையும் 30ஆவது இறுதிக் காதை 'வரந்தரு காதை' ஆகும்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":606,"subject":"tamil","testNumber":7,"question":"'உரையிடையிட்ட பாட்டுடைச் செய்யுள்' என்று அழைக்கப்படும் காப்பியம் எது?","options":["மணிமேகலை","சீவக சிந்தாமணி","சிலப்பதிகாரம்","பெருங்கதை"],"correctAnswer":2,"explanation":"செய்யுட்களுக்கு இடையே உரைநடைப் பகுதிகளும், இசைப் பாடல்களும் அமைந்துள்ளதால் சிலப்பதிகாரம் 'உரையிடையிட்ட பாட்டுடைச் செய்யுள்' எனப் பதிகத்தில் குறிப்பிடப்படுகிறது. இது இயல், இசை, நாடகம் ஆகிய மூன்றையும் உள்ளடக்கியது.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":607,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் கோவலனின் தந்தை மற்றும் கண்ணகியின் தந்தை முறையே யாவர்?","options":["மாநாய்கன், மாசாத்துவான்","மாசாத்துவான், மாநாய்கன்","மாசாத்துவான், கந்துக்கடன்","சச்சந்தன், மாநாய்கன்"],"correctAnswer":1,"explanation":"பூம்புகாரில் வாழ்ந்த பெருவணிகரான மாசாத்துவானின் மகன் கோவலன் ஆவார். கடல் வணிகரான மாநாய்கனின் மகள் கண்ணகி ஆவார். இவ்விரு பெருங்குடிகளின் திருமணத்துடன் சிலப்பதிகாரக் கதை தொடங்குகிறது.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":608,"subject":"tamil","testNumber":7,"question":"மாதவி தனது நடன அரங்கேற்றத்தின்போது சோழ மன்னனிடமிருந்து பெற்ற சிறப்புப் பட்டம் மற்றும் பரிசு எது?","options":["தலைக்கோல் பட்டமும் ஆயிரத்தெட்டு கழஞ்சுப் பொன்னும்","கலைமணிப் பட்டமும் நூறு கழஞ்சுப் பொன்னும்","முத்தமிழ்ப் பட்டமும் ஆயிரம் பொற்காசுகளும்","ஆடலரசிப் பட்டமும் பச்சைமாலையும்"],"correctAnswer":0,"explanation":"சிலப்பதிகாரத்தின் அரங்கேற்று காதையில், மாதவி தன் 12ஆம் வயதில் சோழ மன்னன் அவையில் ஆடல் அரங்கேற்றம் செய்தாள். அவளது திறமையைப் பாராட்டி மன்னன் 'தலைக்கோல்' பட்டமும், 1,008 கழஞ்சுப் பொன் மதிப்புடைய பச்சைமாலையும் பரிசாக வழங்கினான்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":609,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் கோவலன் மாதவியைப் பிரிவதற்குக் காரணமாக அமைந்த காதை எது?","options":["வேனிற்காதை","அந்திமாலைச் சிறப்புசெய் காதை","கடலாடு காதை","கானல்வரி"],"correctAnswer":3,"explanation":"பூம்புகார் கடற்கரையில் கோவலனும் மாதவியும் யாழ் மீட்டிப் பாடிய 'கானல்வரி'ப் பாடல்களில் இருவருக்கும் இடையே ஊடலும் ஐயமும் ஏற்பட்டன. மாதவி வேறொருவன் மீது மனங்கொண்டாள் எனத் தவறாகக் கருதிய கோவலன் அவளைப் பிரிந்து கண்ணகியிடம் திரும்பினான்.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":610,"subject":"tamil","testNumber":7,"question":"கோவலனும் கண்ணகியும் புகாரிலிருந்து மதுரைக்குச் சென்றபோது அவர்களுக்கு வழித்துணையாகச் சென்ற சமணத் துறவி யார்?","options":["அறவண அடிகள்","அச்சணந்தி","கவுந்தியடிகள்","மாடல மறையோன்"],"correctAnswer":2,"explanation":"கோவலனும் கண்ணகியும் புகாரை விட்டு மதுரைக்குப் புறப்பட்டபோது, சமணப் பெண் துறவியான கவுந்தியடிகள் அவர்களுக்கு வழிகாட்டியாகவும் பாதுகாப்பாகவும் உடன் சென்றார். மதுரையில் ஆயர்குல மூதாட்டி மாதரியிடம் கண்ணகியை அடைக்கலமாக ஒப்படைத்தார்.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":611,"subject":"tamil","testNumber":7,"question":"'நெஞ்சை அள்ளும் சிலப்பதிகாரம் என்றோர் மணியாரம் படைத்த தமிழ்நாடு' என்று சிலப்பதிகாரத்தைப் புகழ்ந்து பாடியவர் யார்?","options":["பாரதிதாசன்","மகாகவி பாரதியார்","கவிமணி தேசிக விநாயகம் பிள்ளை","நாமக்கல் கவிஞர்"],"correctAnswer":1,"explanation":"மகாகவி சுப்பிரமணிய பாரதியார் 'செந்தமிழ் நாடு' என்ற தமது பாடலில் 'நெஞ்சை அள்ளும் சிலப்பதிகாரம் என்றோர் மணியாரம் படைத்த தமிழ்நாடு' எனச் சிலப்பதிகாரத்தின் இலக்கியச் சுவையைப் பாராட்டியுள்ளார்.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":612,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தின் 'வழக்குரை காதை'யில் கண்ணகி உடைத்த காற்சிலம்பினுள் இருந்த பரல்கள் எவை?","options":["முத்துப் பரல்கள்","பவளப் பரல்கள்","மாணிக்கப் பரல்கள்","வைரப் பரல்கள்"],"correctAnswer":2,"explanation":"பாண்டிய அரசி கோப்பெருந்தேவியின் சிலம்பினுள் முத்துப் பரல்கள் இருந்தன; கண்ணகியின் சிலம்பினுள் மாணிக்கப் பரல்கள் இருந்தன. கண்ணகி தன் சிலம்பைப் பாண்டியன் அவையில் உடைத்தபோது அதிலிருந்து மாணிக்கப் பரல் தெறித்து மன்னனின் வாயில் விழுந்தது.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":613,"subject":"tamil","testNumber":7,"question":"'யானோ அரசன்; யானே கள்வன்; மன்பதை காக்கும் தென்புலம் காவல் என்முதல் பிழைத்தது; கெடுக என் ஆயுள்' எனக் கூறி உயிர் நீத்த மன்னன் யார்?","options":["சேரன் செங்குட்டுவன்","கரிகாற் பெருவளத்தான்","தலையாலங்கானத்துச் செருவென்ற நெடுஞ்செழியன்","ஆரியப்படை கடந்த பாண்டியன் நெடுஞ்செழியன்"],"correctAnswer":3,"explanation":"கோவலனைத் தீர விசாரிக்காமல் கொன்ற தவறை உணர்ந்த ஆரியப்படை கடந்த பாண்டியன் நெடுஞ்செழியன், தன் செங்கோல் வளைந்ததை எண்ணி 'யானோ அரசன் யானே கள்வன்' என்று கூறி அரியணையிலிருந்து மயங்கி வீழ்ந்து உயிர் நீத்தான்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":614,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் 'திங்களைப் போற்றுதும் திங்களைப் போற்றுதும்', 'ஞாயிறு போற்றுதும்', 'மாமழை போற்றுதும்' என இயற்கையை வாழ்த்திப் பாடப்படும் காதை எது?","options":["மங்கல வாழ்த்துப் பாடல்","வேட்டுவ வரி","ஆய்ச்சியர் குரவை","குன்றக் குரவை"],"correctAnswer":0,"explanation":"இளங்கோவடிகள் சிலப்பதிகாரத்தின் முதல் காதையான 'மங்கல வாழ்த்துப் பாடல்' பகுதியில் கடவுளுக்குப் பதிலாக நிலவு, கதிரவன், மழை, பூம்புகார் ஆகிய இயற்கைப் பொருள்களைப் போற்றி வணங்கி நூலைத் தொடங்குகிறார்.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":615,"subject":"tamil","testNumber":7,"question":"'அடிகள் நீரே அருளுக' என்று இளங்கோவடிகளிடம் சிலப்பதிகாரம் இயற்றுமாறு வேண்டியவர் யார்?","options":["சேரன் செங்குட்டுவன்","சீத்தலைச் சாத்தனார்","நக்கீரர்","கபிலர்"],"correctAnswer":1,"explanation":"கண்ணகியின் வரலாற்றை அறிந்த சீத்தலைச் சாத்தனார், மூவேந்தர்களுக்கும் பொதுவான இக்கதையை இயற்ற இளங்கோவடிகளே தகுதியானவர் எனக் கருதி 'அடிகள் நீரே அருளுக' என்றார். அதற்கு இளங்கோவடிகள் 'நாட்டுதும் யாம் ஓர் பாட்டுடைச் செய்யுள்' எனப் பதிலளித்தார்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":616,"subject":"tamil","testNumber":7,"question":"சேரன் செங்குட்டுவன் வஞ்சி மாநகரில் கண்ணகிக்குப் பத்தினிக் கோட்டம் அமைத்துச் செய்த சிறப்பில் கலந்துகொண்ட இலங்கை அரசன் யார்?","options":["நூற்றுவர் கன்னர்","கயவாகு","ஆரிய அரசன் கனகன்","விசயன்"],"correctAnswer":1,"explanation":"சேரன் செங்குட்டுவன் இமயத்திலிருந்து கல் கொண்டு வந்து கங்கையில் நீராட்டி, வஞ்சியில் கண்ணகிக்குக் கோயில் கட்டினான். அத்திருக்கோயில் வழிபாட்டு விழாவில் கடல்சூழ் இலங்கை மன்னனான கயவாகு கலந்துகொண்டு தன் நாட்டிலும் பத்தினி வழிபாட்டைத் தொடங்கினான்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":617,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்திற்குப் பழமையான உரையை எழுதியவரும், மிகச்சிறந்த விரிவான உரையை எழுதியவரும் முறையே யாவர்?","options":["பரிமேலழகர், நச்சினார்க்கினியர்","இளம்பூரணர், சேனாவரையர்","அரும்பத உரையாசிரியர், அடியார்க்கு நல்லார்","மயிலைநாதர், பேராசிரியர்"],"correctAnswer":2,"explanation":"சிலப்பதிகாரத்திற்கு முதலில் சுருக்கமான பழைய உரை எழுதியவர் அரும்பத உரையாசிரியர் (பெயர் தெரியவில்லை). அதனைத் தழுவி இசை, நாடக நுணுக்கங்களுடன் சிறந்த விரிவான உரை எழுதியவர் அடியார்க்கு நல்லார் ஆவார்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":618,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தை முதன்முதலில் அரும்பத உரை மற்றும் அடியார்க்கு நல்லார் உரையுடன் பதிப்பித்து வெளியிட்டவர் யார்?","options":["சி.வை.தாமோதரம்பிள்ளை","உ.வே.சாமிநாதையர்","ஆறுமுக நாவலர்","ந.மு.வேங்கடசாமி நாட்டார்"],"correctAnswer":1,"explanation":"தமிழ்த்தாத்தா உ.வே.சாமிநாதையர் 1892ஆம் ஆண்டு சிலப்பதிகாரத்தை மூலமும் அரும்பத உரை, அடியார்க்கு நல்லார் உரைகளுடன் முதன்முதலில் செம்பதிப்பாகப் பதிப்பித்துத் தமிழுலகிற்கு வழங்கினார்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":619,"subject":"tamil","testNumber":7,"question":"பூம்புகாரில் இந்திரவிழா எத்தனை நாட்கள் கொண்டாடப்பட்டதாகச் சிலப்பதிகாரத்தின் 'இந்திரவிழா ஊரெடுத்த காதை' குறிப்பிடுகிறது?","options":["18 நாட்கள்","21 நாட்கள்","28 நாட்கள்","30 நாட்கள்"],"correctAnswer":2,"explanation":"சிலப்பதிகாரத்தின் இந்திரவிழா ஊரெடுத்த காதையில், காவிரிப்பூம்பட்டினத்தில் சித்திரைத் திங்களில் 'இருபத்தெட்டு நாட்கள்' (நால்வேழ நாள்) இந்திரவிழா சிறப்பாகக் கொண்டாடப்பட்ட செய்தி இடம்பெற்றுள்ளது.","difficulty":"hard","topic":"சிலப்பதிகாரம்"},{"id":620,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் 'தேரா மன்னா செப்புவதுடையேன்' என்ற புகழ்பெற்ற தொடர் இடம்பெற்றுள்ள காதை எது?","options":["கொலைக்களக் காதை","துன்பமாலை","ஊர்சூழ்வரி","வழக்குரை காதை"],"correctAnswer":3,"explanation":"மதுரைக்காண்டத்தின் வழக்குரை காதையில், கண்ணகி பாண்டியன் நெடுஞ்செழியன் அரசவைக்குச் சென்று 'தேரா மன்னா செப்புவதுடையேன்' (ஆராய்ந்து பாராத மன்னனே, உன்னிடம் சொல்வதற்கு ஒன்று உள்ளது) என்று தன் வழக்கை உரைக்கிறாள்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":621,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் இளங்கோவடிகளின் பெற்றோராகக் குறிப்பிடப்படுபவர்கள் யாவர்?","options":["இமயவரம்பன் நெடுஞ்சேரலாதன் - நற்சோணை","சேரன் செங்குட்டுவன் - வேண்மாள்","கரிகாலன் - வேளாவிக் கோமான் மகள்","செல்வக்கடுங்கோ வாழியாதன் - பதுமன் தேவி"],"correctAnswer":0,"explanation":"இளங்கோவடிகளின் தந்தை சேர மன்னன் இமயவரம்பன் நெடுஞ்சேரலாதன் ஆவார். இவரது தாய் சோழன் மணக்கிள்ளியின் மகளான நற்சோணை ஆவார். சேரன் செங்குட்டுவன் இவரது தமையன் ஆவார்.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":622,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தில் மதுரையில் கண்ணகிக்கு அடைக்கலம் அளித்த ஆயர்குல மூதாட்டி யார்?","options":["தேவந்தி","காவற்பெண்டு","மாதரி","சித்ராபதி"],"correctAnswer":2,"explanation":"மதுரையில் கோவலன்-கண்ணகியைக் கவுந்தியடிகள் ஆயர்குல மூதாட்டியான மாதரியிடம் அடைக்கலமாக ஒப்படைத்தார். மாதரியின் மகள் ஐயை ஆவாள். கோவலன் கொல்லப்பட்ட செய்தியைக் கேட்டு மாதரியும் தீயில் விழுந்து உயிர் நீத்தாள்.","difficulty":"easy","topic":"சிலப்பதிகாரம்"},{"id":623,"subject":"tamil","testNumber":7,"question":"'வடதிசைப் பெயர்ந்த மாபெரும் பத்தினி' எனப் போற்றப்படும் கண்ணகிக்குக் கல் எடுக்கச் சேரன் செங்குட்டுவன் வென்ற வடநாட்டு ஆரிய அரசர்கள் யாவர்?","options":["கனகன், விசயன்","நூற்றுவர் கன்னர், சஞ்சயன்","கயவாகு, பாலகுமாரன்","வச்சிரன், அவந்தி"],"correctAnswer":0,"explanation":"சேரன் செங்குட்டுவன் கண்ணகிக்குச் சிலை வடிக்க இமயத்திற்குப் படையெடுத்துச் சென்றபோது, தமிழரை இகழ்ந்து பேசிய வடநாட்டு ஆரிய அரசர்களான கனகன், விசயன் ஆகியோரைப் போரில் வென்று, அவர்கள் தலையில் கண்ணகி சிலைக்கான கல்லைச் சுமக்கச் செய்தான்.","difficulty":"hard","topic":"சிலப்பதிகாரம்"},{"id":624,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரத்தின் அடியார்க்கு நல்லார் உரை தற்போது எத்தனை காதைகளுக்கு மட்டுமே முழுமையாகக் கிடைத்துள்ளது?","options":["12 காதைகள்","18 காதைகள்","24 காதைகள்","30 காதைகள்"],"correctAnswer":1,"explanation":"அடியார்க்கு நல்லார் சிலப்பதிகாரம் முழுமைக்கும் உரை எழுதியிருந்தாலும், காலப்போக்கில் சில பகுதிகள் அழிந்துபோயின. தற்போது அவருடைய உரை 18 காதைகளுக்கு மட்டுமே கிடைத்துள்ளது; எஞ்சிய பகுதிகளுக்கு அரும்பத உரை துணைநிற்கிறது.","difficulty":"hard","topic":"சிலப்பதிகாரம்"},{"id":625,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரம் 'மூவேந்தர் காப்பியம்' அல்லது 'ஒற்றுமைக் காப்பியம்' என அழைக்கப்படக் காரணம் என்ன?","options":["மூவேந்தர்களின் போர் வெற்றிகளை மட்டுமே பாடுவதால்","சோழ, பாண்டிய, சேர ஆகிய மூன்று நாடுகளின் தலைநகரங்களிலும் கதை நிகழ்வதால்","மூன்று அரசர்களால் இணைந்து இயற்றப்பட்டதால்","மூன்று சமயங்களின் கோட்பாடுகளை மட்டும் கூறுவதால்"],"correctAnswer":1,"explanation":"சிலப்பதிகாரக் கதை சோழ நாட்டின் புகார், பாண்டிய நாட்டின் மதுரை, சேர நாட்டின் வஞ்சி ஆகிய மூவேந்தர்களின் தலைநகரங்களிலும் நிகழ்வதாலும், மூவேந்தரையும் சமமாகப் போற்றுவதாலும் இது 'மூவேந்தர் காப்பியம்' மற்றும் 'ஒற்றுமைக் காப்பியம்' என அழைக்கப்படுகிறது.","difficulty":"medium","topic":"சிலப்பதிகாரம்"},{"id":626,"subject":"tamil","testNumber":7,"question":"மணிமேகலைக் காப்பியத்தை இயற்றிய சீத்தலைச் சாத்தனாரை 'தண்டமிழ் ஆசான்' எனப் பாராட்டியவர் யார்?","options":["கம்பர்","திருவள்ளுவர்","இளங்கோவடிகள்","நக்கீரர்"],"correctAnswer":2,"explanation":"மணிமேகலைக் காப்பியத்தை இயற்றிய மதுரைக் கூலவாணிகன் சீத்தலைச் சாத்தனார் இளங்கோவடிகளின் சமகாலத்தவர். இவரை இளங்கோவடிகள் சிலப்பதிகாரத்தில் 'தண்டமிழ் ஆசான்', 'சாத்தன்', 'நன்னூற்புலவன்' எனப் போற்றியுள்ளார்.","difficulty":"easy","topic":"மணிமேகலை"},{"id":627,"subject":"tamil","testNumber":7,"question":"மணிமேகலைக் காப்பியத்தின் அமைப்பு குறித்த சரியான கூற்று எது?","options":["3 காண்டங்கள், 30 காதைகள் கொண்டது","காண்டப் பிரிவு இன்றி 30 காதைகளை மட்டும் கொண்டது","13 இலம்பகங்களைக் கொண்டது","6 காண்டங்கள், 30 காதைகள் கொண்டது"],"correctAnswer":1,"explanation":"சிலப்பதிகாரத்தைப் போல மணிமேகலையும் 30 காதைகளைக் கொண்டது; ஆனால் சிலப்பதிகாரத்தைப் போல இதில் காண்டப் பிரிவு இல்லை. இதன் முதல் காதை 'விழாவறை காதை', இறுதிக் காதை 'பவத்திறம் அறுக எனப் பாவை நோற்ற காதை' ஆகும்.","difficulty":"medium","topic":"மணிமேகலை"},{"id":628,"subject":"tamil","testNumber":7,"question":"மணிமேகலைக்கு அமுதசுரபி என்ற அட்சய பாத்திரம் எந்தத் தீவில் உள்ள பொய்கையிலிருந்து கிடைத்தது?","options":["மணிபல்லவத் தீவு - கோமுகிப் பொய்கை","இலங்கைத் தீவு - தாமரைப் பொய்கை","சாவகத் தீவு - ஆபுத்திரன் பொய்கை","நாகநாடு - இலஞ்சிப் பொய்கை"],"correctAnswer":0,"explanation":"மணிமேகலா தெய்வத்தால் மணிபல்லவத் தீவிற்கு அழைத்துச் செல்லப்பட்ட மணிமேகலைக்கு, அங்குள்ள கோமுகிப் பொய்கையில் வைகாசித் திங்கள் முழுநிலவு நாளில் அள்ள அள்ளக் குறையாத அமுதம் தரும் 'அமுதசுரபி' பாத்திரம் கிடைத்தது.","difficulty":"easy","topic":"மணிமேகலை"},{"id":629,"subject":"tamil","testNumber":7,"question":"மணிமேகலையின் கையிலிருந்த அமுதசுரபியில் முதன்முதலில் பிச்சையிட்ட கற்புக்கரசி யார்?","options":["காயசண்டிகை","சுதமதி","ஆதிரை","மாதவி"],"correctAnswer":2,"explanation":"அறவண அடிகளின் அறிவுரைப்படி, மணிமேகலை முதன்முதலில் கற்புக்கரசியான ஆதிரையின் இல்லத்திற்குச் சென்று பிச்சை ஏற்றாள். ஆதிரை இட்ட உணவின் மூலம் அமுதசுரபி வற்றாமல் உணவு வழங்கத் தொடங்கியது.","difficulty":"easy","topic":"மணிமேகலை"},{"id":630,"subject":"tamil","testNumber":7,"question":"'உண்டி கொடுத்தோர் உயிர் கொடுத்தோரே' என்ற புகழ்பெற்ற அடி இடம்பெறும் காப்பியம் எது?","options":["சிலப்பதிகாரம்","மணிமேகலை","சீவக சிந்தாமணி","வளையாபதி"],"correctAnswer":1,"explanation":"பசிப்பிணி போக்குவதன் பெருமையை உணர்த்தும் 'உண்டி கொடுத்தோர் உயிர் கொடுத்தோரே' என்ற புகழ்பெற்ற அடி மணிமேகலைக் காப்பியத்தில் (பாத்திரம் பெற்ற காதை) இடம்பெற்றுள்ளது. இது புறநானூற்றிலும் (குடபுலவியனார் பாடல்) உள்ளது.","difficulty":"easy","topic":"மணிமேகலை"},{"id":631,"subject":"tamil","testNumber":7,"question":"சிலப்பதிகாரமும் மணிமேகலையும் 'இரட்டைக் காப்பியங்கள்' என அழைக்கப்படாத காரணங்களில் ஒன்று எது?","options":["கதைத் தொடர்பு உடையவை","இரண்டும் 30 காதைகள் மற்றும் ஆசிரியப்பாவால் ஆனவை","இரண்டும் ஒரே ஆசிரியரால் இயற்றப்பட்டவை","இரண்டும் ஒரே காலத்தைச் சேர்ந்தவை"],"correctAnswer":2,"explanation":"சிலப்பதிகாரம் இளங்கோவடிகளாலும், மணிமேகலை சீத்தலைச் சாத்தனாராலும் இயற்றப்பட்டவை; ஒரே ஆசிரியரால் எழுதப்பட்டவை அல்ல. கதைத் தொடர்பு, கால ஒற்றுமை, 30 காதை அமைப்பு மற்றும் ஆசிரியப்பா ஆகியவற்றால் இவை இரட்டைக் காப்பியங்கள் எனப்படுகின்றன.","difficulty":"medium","topic":"மணிமேகலை"},{"id":632,"subject":"tamil","testNumber":7,"question":"மணிமேகலைக் காப்பியத்தில் 'யானைத்தீ' என்னும் தீராத பசி நோயால் துன்புற்று மணிமேகலையால் பசி தீர்க்கப்பட்டவள் யார்?","options":["காயசண்டிகை","சுதமதி","சித்ராபதி","தீவதிலகை"],"correctAnswer":0,"explanation":"விஞ்சையர் மகளான காயசண்டிகை சாபத்தால் 'யானைத்தீ' எனப்படும் தீராத பசி நோயால் துன்புற்றாள். ஆதிரையிடம் பிச்சை பெற்ற பிறகு மணிமேகலை முதன்முதலாக அமுதசுரபியிலிருந்து உணவு அளித்துக் காயசண்டிகையின் பசிப்பிணியைப் போக்கினாள்.","difficulty":"medium","topic":"மணிமேகலை"},{"id":633,"subject":"tamil","testNumber":7,"question":"மணிமேகலை எந்தச் சமயக் கோட்பாடுகளைப் பரப்புவதற்காக இயற்றப்பட்ட தமிழின் முதல் சமயக் காப்பியம் ஆகும்?","options":["சமண சமயம்","சைவ சமயம்","வைணவ சமயம்","பௌத்த சமயம்"],"correctAnswer":3,"explanation":"மணிமேகலை பௌத்த சமயக் கருத்துகளை எடுத்துரைக்கும் தமிழின் முதல் சமயக் காப்பியம் ஆகும். பசிப்பிணி போக்கல், கள் உண்ணாமை, கொல்லாமை, சிறைச்சாலையை அறச்சாலையாக்குதல் போன்ற அறக்கருத்துகளை இது வலியுறுத்துகிறது.","difficulty":"easy","topic":"மணிமேகலை"},{"id":634,"subject":"tamil","testNumber":7,"question":"மணிமேகலையில் 'அறம் எனப்படுவது யாதெனக் கேட்பின் மறவாது இது கேள் மன்னுயிர்க் கெல்லாம் உண்டியும் உடையும் உறையுளும் அல்லது கண்டதில்' என்று கூறுபவர் யார்?","options":["அறவண அடிகள்","ஆபுத்திரன்","மணிமேகலை","தீவதிலகை"],"correctAnswer":1,"explanation":"மணிமேகலையின் 'ஆபுத்திரன் திறம் அறிவித்த காதை'யில், மனித குலத்திற்குத் தேவையான அடிப்படை அறம் உணவு, உடை, உறையுள் ஆகிய மூன்றும் அளிப்பதே என்று ஆபுத்திரன் வரலாற்றின் வழி சீத்தலைச் சாத்தனார் குறிப்பிடுகிறார்.","difficulty":"hard","topic":"மணிமேகலை"},{"id":635,"subject":"tamil","testNumber":7,"question":"மணிமேகலைக்குப் பௌத்த சமய அறக்கருத்துகளை உபதேசித்த துறவி யார்?","options":["கவுந்தியடிகள்","அறவண அடிகள்","அச்சணந்தி","நாகசேனர்"],"correctAnswer":1,"explanation":"பௌத்தப் பெரியாரான அறவண அடிகள் மணிமேகலைக்குப் பௌத்த தத்துவங்களையும், தவநெறிகளையும் உபதேசித்தார். நூலின் இறுதியில் காஞ்சி மாநகரில் அறவண அடிகளிடம் தீட்சை பெற்று மணிமேகலை தவவாழ்வு மேற்கொண்டாள்.","difficulty":"easy","topic":"மணிமேகலை"},{"id":636,"subject":"tamil","testNumber":7,"question":"தமிழில் விருத்தப்பாவில் அமைந்த முதல் காப்பியம் எது? அதன் ஆசிரியர் யார்?","options":["சீவக சிந்தாமணி - திருத்தக்கதேவர்","கம்பராமாயணம் - கம்பர்","சூளாமணி - தோலாமொழித்தேவர்","வளையாபதி - நாதகுத்தனார்"],"correctAnswer":0,"explanation":"சமணத் துறவியான திருத்தக்கதேவர் இயற்றிய 'சீவக சிந்தாமணி' தமிழில் விருத்தப்பாவில் அமைந்த முதல் காப்பியம் ஆகும். இதன் விருத்தப்பா நடை பிற்காலத்தில் கம்பராமாயணம் உள்ளிட்ட பல காப்பியங்களுக்கு வழிகாட்டியாக அமைந்தது.","difficulty":"easy","topic":"சீவக சிந்தாமணி"},{"id":637,"subject":"tamil","testNumber":7,"question":"சீவக சிந்தாமணி எத்தனை இலம்பகங்களையும் பாடல்களையும் கொண்டது?","options":["10 இலம்பகங்கள், 3,000 பாடல்கள்","12 இலம்பகங்கள், 3,145 பாடல்கள்","13 இலம்பகங்கள், 3,145 பாடல்கள்","15 இலம்பகங்கள், 3,615 பாடல்கள்"],"correctAnswer":2,"explanation":"சீவக சிந்தாமணி 13 இலம்பகங்களையும் 3,145 விருத்தப்பாடல்களையும் கொண்டது. இதன் முதல் இலம்பகம் 'நாமகள் இலம்பகம்' ஆகும்; இறுதி இலம்பகம் 'முத்தி இலம்பகம்' ஆகும்.","difficulty":"medium","topic":"சீவக சிந்தாமணி"},{"id":638,"subject":"tamil","testNumber":7,"question":"சீவக சிந்தாமணிக்கு வழங்கப்படும் சிறப்புப் பெயர்களில் தவறானது எது?","options":["மணநூல்","முக்தி நூல்","இயற்கை தவம்","அறக்காப்பியம்"],"correctAnswer":3,"explanation":"சீவகன் எட்டுப் பெண்களை மணந்து முடிவில் துறவு பூண்டு முத்தி பெறுவதால் சீவக சிந்தாமணி 'மணநூல்', 'காமநூல்', 'முக்தி நூல்', 'இயற்கை தவம்' என அழைக்கப்படுகிறது. 'அறக்காப்பியம்' என்பது மணிமேகலையின் சிறப்புப் பெயராகும்.","difficulty":"medium","topic":"சீவக சிந்தாமணி"},{"id":639,"subject":"tamil","testNumber":7,"question":"சீவக சிந்தாமணிக்குச் சிறந்த உரை எழுதிய உரையாசிரியர் யார்?","options":["அடியார்க்கு நல்லார்","நச்சினார்க்கினியர்","பரிமேலழகர்","சேனாவரையர்"],"correctAnswer":1,"explanation":"உரையாசிரியர்களில் சிறந்தவரான நச்சினார்க்கினியர் சீவக சிந்தாமணிக்கு அரிய உரை எழுதியுள்ளார். இவ்வுரையுடன் உ.வே.சாமிநாதையர் 1887ஆம் ஆண்டு சீவக சிந்தாமணியை முதன்முதலில் பதிப்பித்தார்.","difficulty":"medium","topic":"சீவக சிந்தாமணி"},{"id":640,"subject":"tamil","testNumber":7,"question":"சீவக சிந்தாமணியின் ஆசிரியரான திருத்தக்கதேவர், தாம் இன்பச்சுவை மிக்க காப்பியம் பாட வல்லவர் என்பதை நிரூபிக்க அதற்கு முன்னர் இயற்றிய நூல் எது?","options":["எலிவிருத்தம்","கிளிவிருத்தம்","நரிவிருத்தம்","மயில்விருத்தம்"],"correctAnswer":2,"explanation":"சமணத் துறவிகள் துறவு நெறியே பாடுவர், அகப்பொருள் பாட இயலாது என்ற கருத்தை மாற்றத் திருத்தக்கதேவர் முதலில் நிலையாமை உணர்த்தும் 'நரிவிருத்தம்' என்ற நூலைப் பாடினார்; அதன் பின்னர் சீவக சிந்தாமணியை இயற்றினார்.","difficulty":"hard","topic":"சீவக சிந்தாமணி"},{"id":641,"subject":"tamil","testNumber":7,"question":"சீவக சிந்தாமணியில் சீவகனின் பெற்றோர் மற்றும் அவனுக்குக் கல்வி கற்பித்த ஆசிரியர் முறையே யாவர்?","options":["சச்சந்தன் - விசயை; அச்சணந்தி","கந்துக்கடன் - சுநந்தை; அறவண அடிகள்","கட்டியங்காரன் - விசயை; அச்சணந்தி","சச்சந்தன் - காந்தருவதத்தை; நாதகுத்தனார்"],"correctAnswer":0,"explanation":"ஏமாங்கத நாட்டு மன்னன் சச்சந்தனுக்கும் விசயைக்கும் பிறந்தவன் சீவகன். கந்துக்கடன் என்ற வணிகனால் வளர்க்கப்பட்ட சீவகனுக்கு அச்சணந்தி என்ற ஆசிரியர் சகல கலைகளையும் கற்பித்தார்.","difficulty":"hard","topic":"சீவக சிந்தாமணி"},{"id":642,"subject":"tamil","testNumber":7,"question":"ஐம்பெருங்காப்பியங்களுள் ஒன்றான 'குண்டலகேசி'யை இயற்றியவர் மற்றும் அது சார்ந்த சமயம் முறையே எவை?","options":["தோலாமொழித்தேவர், சமண சமயம்","நாதகுத்தனார், பௌத்த சமயம்","திருத்தக்கதேவர், சமண சமயம்","ஆசிரியர் பெயர் தெரியவில்லை, பௌத்த சமயம்"],"correctAnswer":1,"explanation":"குண்டலகேசியை இயற்றியவர் நாதகுத்தனார் ஆவார். இது பௌத்த சமயக் காப்பியமாகும். 'குண்டலகேசி விருத்தம்' என்றும் அழைக்கப்படும் இந்நூலின் 19 முழுப் பாடல்கள் மட்டுமே தற்போது கிடைத்துள்ளன.","difficulty":"easy","topic":"வளையாபதி & குண்டலகேசி"},{"id":643,"subject":"tamil","testNumber":7,"question":"'வளையாபதி' காப்பியம் குறித்த பின்வரும் கூற்றுகளில் சரியானது எது?","options":["இது பௌத்த சமயக் காப்பியமாகும்; ஆசிரியர் நாதகுத்தனார்","இது முழுமையாகக் கிடைத்துள்ள சமணக் காப்பியமாகும்","இது சமண சமயக் காப்பியமாகும்; ஆசிரியர் பெயர் தெரியவில்லை","இது ஐஞ்சிறுகாப்பியங்களுள் ஒன்றாகும்"],"correctAnswer":2,"explanation":"வளையாபதி ஐம்பெருங்காப்பியங்களுள் ஒன்றான சமண சமயக் காப்பியமாகும். இதன் ஆசிரியர் பெயர் தெரியவில்லை. இந்நூல் முழுமையாகக் கிடைக்கவில்லை; புறத்திரட்டு போன்ற தொகுப்பு நூல்கள் வழி 72 பாடல்கள் மட்டுமே கிடைத்துள்ளன.","difficulty":"medium","topic":"வளையாபதி & குண்டலகேசி"},{"id":644,"subject":"tamil","testNumber":7,"question":"பௌத்த சமயக் காப்பியமான 'குண்டலகேசி'க்கு மறுப்பாக எழுந்த சமண சமயத் தருக்கக் காப்பியம் எது?","options":["சூளாமணி","யசோதர காவியம்","நாககுமார காவியம்","நீலகேசி"],"correctAnswer":3,"explanation":"பௌத்த சமயக் கருத்துகளை நிலைநாட்ட எழுந்த குண்டலகேசிக்கு மறுப்பாகச் சமண சமயத்தவரால் இயற்றப்பட்ட ஐஞ்சிறுகாப்பிய நூல் 'நீலகேசி' ஆகும். இது தமிழின் முதல் தருக்க நூல் (வாத நூல்) எனப் போற்றப்படுகிறது.","difficulty":"easy","topic":"வளையாபதி & குண்டலகேசி"},{"id":645,"subject":"tamil","testNumber":7,"question":"ஐம்பெருங்காப்பியங்களுள் பௌத்த சமயத்தைச் சார்ந்த இரு காப்பியங்கள் எவை?","options":["சிலப்பதிகாரம், மணிமேகலை","சீவக சிந்தாமணி, வளையாபதி","மணிமேகலை, குண்டலகேசி","வளையாபதி, குண்டலகேசி"],"correctAnswer":2,"explanation":"ஐம்பெருங்காப்பியங்களுள் மணிமேகலையும் குண்டலகேசியும் பௌத்த சமயக் காப்பியங்கள் ஆகும். சிலப்பதிகாரம், சீவக சிந்தாமணி, வளையாபதி ஆகிய மூன்றும் சமண சமயச் சார்புடைய காப்பியங்களாகும்.","difficulty":"easy","topic":"வளையாபதி & குண்டலகேசி"},{"id":646,"subject":"tamil","testNumber":7,"question":"ஐஞ்சிறுகாப்பியங்கள் ஐந்தும் எந்தச் சமயத்தைச் சார்ந்தவை?","options":["சமண சமயம்","பௌத்த சமயம்","சைவ சமயம்","வைணவ சமயம்"],"correctAnswer":0,"explanation":"சூளாமணி, நீலகேசி, யசோதர காவியம், உதயணகுமார காவியம், நாககுமார காவியம் ஆகிய ஐஞ்சிறுகாப்பியங்கள் ஐந்தும் சமண சமயத்தைச் சார்ந்த நூல்களாகும். அறம், பொருள், இன்பம், வீடு ஆகிய நான்கினுள் ஒன்றோ பலவோ குறைந்து வருவன சிறுகாப்பியங்கள் எனப்படும்.","difficulty":"easy","topic":"ஐஞ்சிறுகாப்பியங்கள்"},{"id":647,"subject":"tamil","testNumber":7,"question":"ஐஞ்சிறுகாப்பியங்களுள் மிகச் சிறந்ததாகப் போற்றப்படும் 'சூளாமணி' என்னும் காப்பியத்தை இயற்றியவர் யார்?","options":["வெண்ணாவலுடையார் வேள்","கொங்குவேளிர்","தோலாமொழித்தேவர்","திருத்தக்கதேவர்"],"correctAnswer":2,"explanation":"சூளாமணி என்ற ஐஞ்சிறுகாப்பியத்தை இயற்றியவர் தோலாமொழித்தேவர் ஆவார். இது விருத்தப்பாவால் ஆன சமணக் காப்பியம்; திவிட்டன், விசயன் ஆகியோரின் வரலாற்றை 12 சருக்கங்களில் 2,131 பாடல்களில் கூறுகிறது.","difficulty":"easy","topic":"ஐஞ்சிறுகாப்பியங்கள்"},{"id":648,"subject":"tamil","testNumber":7,"question":"பொருத்துக (ஐஞ்சிறுகாப்பியங்களும் அவற்றின் சிறப்புகளும்):\n(அ) சூளாமணி - 1. தமிழின் முதல் தருக்க நூல்\n(ஆ) நீலகேசி - 2. பெருங்கதையின் சுருக்கம்\n(இ) யசோதர காவியம் - 3. தோலாமொழித்தேவர்\n(ஈ) உதயணகுமார காவியம் - 4. வெண்ணாவலுடையார் வேள்","options":["அ-3, ஆ-1, இ-4, ஈ-2","அ-3, ஆ-4, இ-1, ஈ-2","அ-1, ஆ-3, இ-4, ஈ-2","அ-4, ஆ-1, இ-2, ஈ-3"],"correctAnswer":0,"explanation":"சூளாமணியை இயற்றியவர் தோலாமொழித்தேவர். நீலகேசி தமிழின் முதல் தருக்க நூலாகும். யசோதர காவியத்தை இயற்றியவர் வெண்ணாவலுடையார் வேள். உதயணகுமார காவியம் கொங்குவேளிரின் பெருங்கதையைச் சுருக்கிப் பாடப்பட்டதாகும்.","difficulty":"medium","topic":"ஐஞ்சிறுகாப்பியங்கள்"},{"id":649,"subject":"tamil","testNumber":7,"question":"ஐஞ்சிறுகாப்பியங்களுள் ஆசிரியர் பெயர் தெரியாத நூல்கள் எவை?","options":["சூளாமணி, நீலகேசி, யசோதர காவியம்","நீலகேசி, உதயணகுமார காவியம், நாககுமார காவியம்","சூளாமணி, உதயணகுமார காவியம், நாககுமார காவியம்","யசோதர காவியம், நீலகேசி, நாககுமார காவியம்"],"correctAnswer":1,"explanation":"ஐஞ்சிறுகாப்பியங்களுள் சூளாமணி (தோலாமொழித்தேவர்) மற்றும் யசோதர காவியம் (வெண்ணாவலுடையார் வேள்) ஆகிய இரு நூல்களின் ஆசிரியர்கள் மட்டுமே அறியப்பட்டுள்ளனர். நீலகேசி, உதயணகுமார காவியம், நாககுமார காவியம் ஆகிய மூன்றின் ஆசிரியர்கள் பெயர் தெரியவில்லை.","difficulty":"hard","topic":"ஐஞ்சிறுகாப்பியங்கள்"},{"id":650,"subject":"tamil","testNumber":7,"question":"'நீலகேசி' காப்பியத்திற்குச் சிறந்த உரை எழுதியவர் யார்?","options":["நச்சினார்க்கினியர்","அடியார்க்கு நல்லார்","சமய திவாகர வாமன முனிவர்","பரிமேலழகர்"],"correctAnswer":2,"explanation":"சமண சமயத் தருக்கக் காப்பியமான நீலகேசிக்கு 'சமய திவாகர விருத்தி' என்ற விரிவான உரையை எழுதியவர் சமய திவாகர வாமன முனிவர் ஆவார். இந்நூல் பிற சமயக் கருத்துகளை மறுத்துச் சமணக் கோட்பாட்டை நிலைநாட்டுகிறது.","difficulty":"hard","topic":"ஐஞ்சிறுகாப்பியங்கள்"},{"id":651,"subject":"tamil","testNumber":7,"question":"கம்பர் தாம் இயற்றிய இராமாயணத்திற்கு இட்ட இயற்பெயர் என்ன?","options":["இராமாவதாரம்","இராமகாதை","இராமசரிதம்","கம்பராமாயணம்"],"correctAnswer":0,"explanation":"வால்மீகி முனிவர் வடமொழியில் இயற்றிய இராமாயணத்தைத் தமிழில் வழிநூலாகப் படைத்த கம்பர், தமது காப்பியத்திற்கு 'இராமாவதாரம்' எனப் பெயரிட்டார். பின்னர் அது கம்பரின் பெயரால் 'கம்பராமாயணம்' என அழைக்கப்பட்டது.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":652,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தில் உள்ள ஆறு காண்டங்களின் சரியான காலவரிசை எது?","options":["பால, அயோத்தியா, கிட்கிந்தா, ஆரண்ய, சுந்தர, யுத்த காண்டம்","பால, ஆரண்ய, அயோத்தியா, கிட்கிந்தா, சுந்தர, யுத்த காண்டம்","பால, அயோத்தியா, ஆரண்ய, சுந்தர, கிட்கிந்தா, யுத்த காண்டம்","பால, அயோத்தியா, ஆரண்ய, கிட்கிந்தா, சுந்தர, யுத்த காண்டம்"],"correctAnswer":3,"explanation":"கம்பராமாயணம் ஆறு காண்டங்களைக் கொண்டது. அவை முறையே பாலகாண்டம், அயோத்தியா காண்டம், ஆரண்ய காண்டம், கிட்கிந்தா காண்டம், சுந்தர காண்டம், யுத்த காண்டம் என்பனவாகும்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":653,"subject":"tamil","testNumber":7,"question":"கம்பரை ஆதரித்த திருவெண்ணெய்நல்லூர் வள்ளல் யார்? அவரைக் கம்பர் எவ்வாறு சிறப்பித்துப் பாடியுள்ளார்?","options":["சடையப்ப வள்ளல் - ஆயிரம் பாடல்களுக்கு ஒரு பாடல் வீதம் பாடியுள்ளார்","சீதக்காதி - நூறு பாடல்களுக்கு ஒரு பாடல் வீதம் பாடியுள்ளார்","சந்திரன் சுவர்க்கி - காண்டத்திற்கு ஒரு பாடல் வீதம் பாடியுள்ளார்","வரபதி ஆட்கொண்டான் - படலத்திற்கு ஒரு பாடல் வீதம் பாடியுள்ளார்"],"correctAnswer":0,"explanation":"கம்பரை ஆதரித்துப் போற்றியவர் திருவெண்ணெய்நல்லூர் சடையப்ப வள்ளல் ஆவார். அவருடைய நன்றியைப் போற்றும் விதமாகக் கம்பர் தமது காப்பியத்தில் ஆயிரம் பாடல்களுக்கு ஒரு பாடல் எனச் சடையப்ப வள்ளலைப் புகழ்ந்து பாடியுள்ளார்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":654,"subject":"tamil","testNumber":7,"question":"'விருத்தமெனும் ஒண்பாவிற்கு உயர் கம்பன்' என்ற தொடர் உணர்த்தும் சிறப்பு என்ன?","options":["கம்பர் வெண்பா பாடுவதில் வல்லவர்","கம்பர் ஆசிரியப்பா பாடுவதில் சிறந்தவர்","கம்பர் கலித்துறை பாடுவதில் உயர்ந்தவர்","கம்பர் விருத்தப்பா பாடுவதில் இணையற்றவர்"],"correctAnswer":3,"explanation":"விருத்தப்பா வகைகளைக் கதைச்சூழலுக்கும் உணர்ச்சிக்கும் ஏற்பப் பல்வேறு சந்த நயங்களுடன் கையாண்டு பாடியதால், 'விருத்தமெனும் ஒண்பாவிற்கு உயர் கம்பன்' எனத் தமிழறிஞர்கள் கம்பரைப் போற்றுகின்றனர்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":655,"subject":"tamil","testNumber":7,"question":"'கல்வியில் பெரியவர் கம்பர்' மற்றும் 'கம்பன் வீட்டுக் கட்டுத்தறியும் கவிபாடும்' ஆகிய சிறப்புத் தொடர்களுக்கு உரிய கம்பர் பிறந்த ஊர் எது?","options":["குன்றத்தூர்","தேரழுந்தூர்","திருவெண்ணெய்நல்லூர்","பொன்விளைந்த களத்தூர்"],"correctAnswer":1,"explanation":"கவிச்சக்கரவர்த்தி கம்பர் சோழ நாட்டில் உள்ள தேரழுந்தூரில் (மயிலாடுதுறை மாவட்டம்) ஆதித்தன் என்பவருக்கு மகனாகப் பிறந்தார். இவரது காலம் கி.பி. 12ஆம் நூற்றாண்டு ஆகும்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":656,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தின் ஏழாவது காண்டமாகக் கருதப்படும் 'உத்தர காண்டம்' என்னும் பகுதியை இயற்றியவர் யார்?","options":["ஒட்டக்கூத்தர்","புகழேந்திப் புலவர்","செயங்கொண்டார்","சேக்கிழார்"],"correctAnswer":0,"explanation":"கம்பர் ஆறு காண்டங்களுடன் (யுத்த காண்டத்தின் நிறைவில் இராமன் முடிசூட்டு விழாவுடன்) தமது காப்பியத்தை நிறைவு செய்தார். அதன் தொடர்ச்சியான 'உத்தர காண்டம்' என்னும் ஏழாவது காண்டத்தைக் கவிச்சக்கரவர்த்தி ஒட்டக்கூத்தர் இயற்றினார்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":657,"subject":"tamil","testNumber":7,"question":"'அண்ணலும் நோக்கினான்; அவளும் நோக்கினாள்' என்ற புகழ்பெற்ற கம்பராமாயண அடி எந்தக் காண்டத்தில் இடம்பெற்றுள்ளது?","options":["அயோத்தியா காண்டம்","ஆரண்ய காண்டம்","சுந்தர காண்டம்","பாலகாண்டம்"],"correctAnswer":3,"explanation":"பாலகாண்டத்தின் 'மிதிலைக் காட்சிப் படலத்தில்', மிதிலை நகர வீதியில் நடந்து வந்த இராமனும், கன்னிமாடத்தில் நின்ற சீதையும் முதன்முதலில் ஒருவரையொருவர் பார்த்துக் கொண்ட காட்சியைக் கம்பர் 'அண்ணலும் நோக்கினான்; அவளும் நோக்கினாள்' என அழகுறப் பாடியுள்ளார்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":658,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தில் இராமன் 'சொல்லின் செல்வன்' என்று யாரைப் பாராட்டினான்?","options":["குகன்","சுக்ரீவன்","அனுமன்","விபீடணன்"],"correctAnswer":2,"explanation":"கிட்கிந்தா காண்டத்தின் அனுமப் படலத்தில், சுக்ரீவனின் தூதுவனாக வந்து ஆழமான அறிவுடனும் சொல்வன்மையுடனும் பேசிய அனுமனை வியந்து, இராமன் இலக்குவனிடம் இவன் 'சொல்லின் செல்வன்' என்று பாராட்டினான்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":659,"subject":"tamil","testNumber":7,"question":"'குகனொடும் ஐவர் ஆனேம் முன்பு பின் குன்று சூழ்வான் மகனொடும் அறுவர் ஆனேம்... நின்னொடும் எழுவர் ஆனேம்' என்று இராமன் யாரிடம் கூறினான்?","options":["விபீடணன்","சுக்ரீவன்","அனுமன்","அங்கதன்"],"correctAnswer":0,"explanation":"யுத்த காண்டத்தின் வீடணன் அடைக்கலப் படலத்தில், தன்னிடம் சரணடைந்த இராவணனின் தம்பி விபீடணனைத் தம்பியாக ஏற்றுக் கொண்ட இராமன், குகனோடு ஐவராகி, சுக்ரீவனோடு அறுவராகி, இப்போது உன்னோடு எழுவரானோம் எனக் கூறிச் சகோதரத்துவத்தைப் போற்றினான்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":660,"subject":"tamil","testNumber":7,"question":"'கண்டனென் கற்பினுக்கு அணியைக் கண்களால்' என்று சீதையைக் கண்ட செய்தியை இராமனிடம் கூறியவர் யார்?","options":["சடாயு","சம்பாதி","அங்கதன்","அனுமன்"],"correctAnswer":3,"explanation":"சுந்தர காண்டத்தின் 'திருவடி தொழுத படலத்தில்', இலங்கையில் அசோகவனத்தில் சீதையைக் கண்டு திரும்பிய அனுமன், இராமனின் துயரை உடனே போக்க 'கண்டனென்' என்ற மங்கலச் சொல்லால் தொடங்கி 'கண்டனென் கற்பினுக்கு அணியைக் கண்களால்' என்று கூறினான்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":661,"subject":"tamil","testNumber":7,"question":"'தமிழுக்குக் கதி' என்று இரு பெரும் புலவர்களைக் குறிப்பிடுவர். அதில் 'க' மற்றும் 'தி' என்பன யாரைக் குறிக்கின்றன?","options":["கம்பர், திருவள்ளுவர்","கபிலர், திருத்தக்கதேவர்","கம்பர், திருமூலர்","கச்சியப்பர், திருநாவுக்கரசர்"],"correctAnswer":0,"explanation":"செல்வக்கேசவராய முதலியார் 'தமிழுக்குக் கதி' என்று கம்பரையும் திருவள்ளுவரையும் சிறப்பித்துக் கூறினார். இதில் 'க' என்பது கம்பராமாயணத்தையும் (கம்பர்), 'தி' என்பது திருக்குறளையும் (திருவள்ளுவர்) குறிக்கும்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":662,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தில் 'இன்று போய் நாளை வா' என்று இராமன் யாரிடம், எந்தக் காண்டத்தில் கூறினான்?","options":["கும்பகர்ணனிடம் - யுத்த காண்டம்","இராவணனிடம் - ஆரண்ய காண்டம்","இந்திரஜித்திடம் - யுத்த காண்டம்","இராவணனிடம் - யுத்த காண்டம்"],"correctAnswer":3,"explanation":"யுத்த காண்டத்தின் முதற்போர் புரி படலத்தில், படைக்கலன்களை இழந்து வெறுங்கையுடன் நின்ற இராவணனைக் கொல்வது போர் அறமன்று எனக் கருதிய இராமன், 'ஆளையுடைய ஐய! இன்று போய் போர்க்கு நாளை வா' என்று உயர்ந்த போர் அறத்தைப் புலப்படுத்தினான்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":663,"subject":"tamil","testNumber":7,"question":"கம்பர் இயற்றிய பிற நூல்களின் தொகுப்பில் பொருந்தாத நூல் எது?","options":["ஏரெழுபது","சடகோபர் அந்தாதி","சரஸ்வதி அந்தாதி","நளவெண்பா"],"correctAnswer":3,"explanation":"ஏரெழுபது, சிலையெழுபது, சடகோபர் அந்தாதி, சரஸ்வதி அந்தாதி, திருக்கை வழக்கம் ஆகியன கம்பர் இயற்றிய பிற நூல்களாகும். 'நளவெண்பா' புகழேந்திப் புலவர் இயற்றிய நூலாகும்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":664,"subject":"tamil","testNumber":7,"question":"'வண்மை இல்லை ஓர் வறுமை இன்மையால்' என்ற கம்பராமாயண அடி எந்த நாட்டின் வளத்தைப் போற்றிப் பாடுகிறது?","options":["கோசல நாடு","மிதிலை நாடு","கிட்கிந்தை","இலங்கை"],"correctAnswer":0,"explanation":"பாலகாண்டத்தின் நாட்டுப்படலத்தில், கோசல நாட்டில் வறுமையே இல்லாததால் அங்கே கொடைத்தன்மை (வண்மை) வெளிப்பட வாய்ப்பு இல்லை எனக் கம்பர் கோசல நாட்டின் செல்வ வளத்தை இல்பொருள் உவமை / தற்குறிப்பேற்ற நயத்துடன் பாடுகிறார்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":665,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தின் கடவுள் வாழ்த்துப் பாடலாக அமைந்துள்ள முதல் பாடலின் தொடக்க அடி எது?","options":["உலகெலாம் உணர்ந்து ஓதற்கரியவன்","உலகம் யாவையும் தாம் உளவாக்கலும்","திங்களைப் போற்றுதும் திங்களைப் போற்றுதும்","அகர முதல எழுத்தெல்லாம் ஆதி"],"correctAnswer":1,"explanation":"'உலகம் யாவையும் தாம் உளவாக்கலும் நிலைபெறுத்தலும் நீக்கலும் நீங்கலா அலகிலா விளையாட்டுடையார்' என்பது கம்பராமாயணத்தின் முதற்பாடலான கடவுள் வாழ்த்துப் பாடலாகும். 'உலகெலாம்' என்பது பெரியபுராணத்தின் தொடக்கமாகும்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":666,"subject":"tamil","testNumber":7,"question":"'யாமறிந்த புலவரிலே கம்பனைப்போல் வள்ளுவர்போல் இளங்கோவைப்போல் பூமிதனில் யாங்கணுமே பிறந்ததில்லை' எனக் கம்பரைப் புகழ்ந்தவர் யார்?","options":["பாரதிதாசன்","நாமக்கல் கவிஞர்","கவிமணி தேசிக விநாயகம் பிள்ளை","மகாகவி பாரதியார்"],"correctAnswer":3,"explanation":"மகாகவி பாரதியார் தமிழின் பெருமையைப் பாடும் 'தமிழ்' என்ற கவிதையில் கம்பர், திருவள்ளுவர், இளங்கோவடிகள் ஆகிய மூவரையும் உலகப் புலவர்களுள் நிகரற்றவர்களாகப் போற்றிப் பாடியுள்ளார். மேலும் 'கம்பன் இசைத்த கவியெல்லாம் நான்' என்றும் பாரதியார் பாடியுள்ளார்.","difficulty":"easy","topic":"கம்பராமாயணம்"},{"id":667,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தில் கங்கைக் கரையில் இராமனை எதிர்கொண்டு வரவேற்ற வேடர் தலைவன் குகன் பற்றிய படலம் எந்தக் காண்டத்தில் உள்ளது?","options":["பாலகாண்டம்","ஆரண்ய காண்டம்","அயோத்தியா காண்டம்","கிட்கிந்தா காண்டம்"],"correctAnswer":2,"explanation":"இராமன் காட்டிற்குச் செல்லும்போது கங்கைக் கரையில் சிருங்கிபேரபுரத்தின் வேடர் தலைவனான குகன் தேனும் மீனும் கொண்டு வந்து தன் தூய அன்பை வெளிப்படுத்தினான். இந்தக் 'குகப்படலம்' அயோத்தியா காண்டத்தில் அமைந்துள்ளது.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":668,"subject":"tamil","testNumber":7,"question":"'தண்டலை மயில்கள் ஆட தாமரை விளக்கம் தாங்க' என்ற கம்பராமாயணப் பாடல் எந்த நிலத்தின் இயற்கை அழகை வருணிக்கிறது?","options":["மருத நிலம்","குறிஞ்சி நிலம்","முல்லை நிலம்","நெய்தல் நிலம்"],"correctAnswer":0,"explanation":"பாலகாண்டத்தின் நாட்டுப்படலத்தில் உள்ள 'தண்டலை மயில்கள் ஆட தாமரை விளக்கம் தாங்க, கொண்டல்கள் முழவின் ஏங்க' என்ற பாடல் கோசல நாட்டின் வயலும் வயல் சார்ந்த மருத நிலத்தின் இயற்கை கொலு வீற்றிருக்கும் காட்சியை வருணிக்கிறது.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":669,"subject":"tamil","testNumber":7,"question":"'வெய்யோன் ஒளி தன் மேனியின் விரிசோதியில் மறைய' என்ற அழகிய பாடலடியில் 'வெய்யோன்' என்பது எதைக் குறிக்கிறது?","options":["நிலவு","மின்னல்","கதிரவன்","நெருப்பு"],"correctAnswer":2,"explanation":"அயோத்தியா காண்டத்தின் கங்கைப் படலத்தில், கதிரவனின் (வெய்யோன்) ஒளி இராமனின் திருமேனி அழகின் ஒளியில் மறைந்து போகுமாறு விளங்கியதைக் கம்பர் 'வெய்யோன் ஒளி தன் மேனியின் விரிசோதியில் மறைய' என வருணித்துள்ளார்.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":670,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தில் 'உறங்குகின்ற கும்பகன்ன உங்கள் மாய வாழ்வெலாம் இறங்குகின்றது இன்று காண் எழுந்திராய் எழுந்திராய்' என்ற பாடல் எந்தக் காண்டத்தில் இடம்பெறுகிறது?","options":["சுந்தர காண்டம்","ஆரண்ய காண்டம்","கிட்கிந்தா காண்டம்","யுத்த காண்டம்"],"correctAnswer":3,"explanation":"யுத்த காண்டத்தின் கும்பகர்ணன் வதைப் படலத்தில், போருக்காக ஆழ்ந்த உறக்கத்திலிருந்த கும்பகர்ணனைப் பணியாளர்கள் எழுப்பும்போது பாடும் ஓசை நயம் மிக்க பாடலாக 'உறங்குகின்ற கும்பகன்ன' என்ற பாடல் அமைந்துள்ளது.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":671,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தின் ஐந்தாவது காண்டமான 'சுந்தர காண்டம்' யார் பெருமையை முதன்மையாகப் போற்றுகிறது?","options":["அனுமனின் வீரமும் சீதையின் கற்பும்","இராமனின் இளமைப் பருவமும் திருமணமும்","பரதனின் பாதுகை ஆட்சியும் குகனின் அன்பும்","சுக்ரீவனின் நட்பும் வாலியின் வதையும்"],"correctAnswer":0,"explanation":"சுந்தர காண்டம் முழுவதும் அனுமனின் ஆற்றல், அறிவுக்கூர்மை, இலங்கைப் பயணம் மற்றும் அசோகவனத்தில் சிறைப்பட்ட சீதையின் கற்புத்திண்மை ஆகியவற்றை அழகுற (சுந்தரம் = அழகு) விவரிக்கிறது.","difficulty":"medium","topic":"கம்பராமாயணம்"},{"id":672,"subject":"tamil","testNumber":7,"question":"'பன்மலர் அடுக்கிய நன்மலர் மாலை' போல் கம்பராமாயணத்தைக் கம்பர் எந்தத் திருக்கோயிலில் அரங்கேற்றம் செய்ததாக வரலாறு கூறுகிறது?","options":["தில்லை நடராசர் கோயில்","திருவரங்கம் அரங்கநாதர் கோயில்","மதுரை மீனாட்சியம்மன் கோயில்","தஞ்சைப் பெருவுடையார் கோயில்"],"correctAnswer":1,"explanation":"கம்பர் தாம் இயற்றிய இராமாவதாரத்தை (கம்பராமாயணம்) திருவரங்கம் திருக்கோயிலில் உள்ள மண்டபத்தில் (கம்பர் மண்டபம்) அறிஞர்கள் முன்னிலையில் அரங்கேற்றம் செய்தார். தில்லையில் அரங்கேற்றப்பட்ட காப்பியம் பெரியபுராணம் ஆகும்.","difficulty":"hard","topic":"கம்பராமாயணம்"},{"id":673,"subject":"tamil","testNumber":7,"question":"பொருத்துக (கம்பராமாயணக் காண்டங்களும் முக்கிய நிகழ்வுகளும்):\n(அ) பாலகாண்டம் - 1. சடாயு உயிர்நீத்த படலம்\n(ஆ) அயோத்தியா காண்டம் - 2. மிதிலைக் காட்சிப் படலம்\n(இ) ஆரண்ய காண்டம் - 3. வாலி வதைப் படலம்\n(ஈ) கிட்கிந்தா காண்டம் - 4. குகப் படலம்","options":["அ-2, ஆ-4, இ-1, ஈ-3","அ-2, ஆ-1, இ-4, ஈ-3","அ-4, ஆ-2, இ-1, ஈ-3","அ-2, ஆ-4, இ-3, ஈ-1"],"correctAnswer":0,"explanation":"பாலகாண்டத்தில் இராமன்-சீதை சந்திக்கும் மிதிலைக் காட்சிப் படலமும், அயோத்தியா காண்டத்தில் குகப் படலமும், ஆரண்ய காண்டத்தில் சீதையைக் காக்கப் போராடிய சடாயு உயிர்நீத்த படலமும், கிட்கிந்தா காண்டத்தில் வாலி வதைப் படலமும் அமைந்துள்ளன.","difficulty":"hard","topic":"கம்பராமாயணம்"},{"id":674,"subject":"tamil","testNumber":7,"question":"'ஆழிசூழ் உலகமெல்லாம் பரதனே ஆள நீ போய் தாழிருங் கானம் சேர்க' என்று கைகேயி இராமனிடம் கூறும் நிகழ்வு எந்தப் படலத்தில் இடம்பெறுகிறது?","options":["மந்தரை சூழ்ச்சிப் படலம்","நகர் நீங்கு படலம்","தைலமாட்டுப் படலம்","கைகேயி சூழ்வினைப் படலம்"],"correctAnswer":3,"explanation":"அயோத்தியா காண்டத்தின் 'கைகேயி சூழ்வினைப் படலத்தில்', மந்தரையின் சூழ்ச்சியால் மனம் மாறிய கைகேயி, பரதன் நாடாளவும் இராமன் பதினான்கு ஆண்டுகள் காடேகவும் தசரதன் ஆணையிட்டதாக இராமனிடம் கூறுகிறாள்.","difficulty":"hard","topic":"கம்பராமாயணம்"},{"id":675,"subject":"tamil","testNumber":7,"question":"கம்பராமாயணத்தில் 'அப்போது மலர்ந்த செந்தாமரையை வென்றது' என இராமனின் முகத்தைக் கம்பர் எந்தச் சூழலில் உவமைப்படுத்துகிறார்?","options":["சீதையை மணந்தபோது","காட்டிற்குச் செல்லுமாறு கைகேயி கூறியபோது","இராவணனைப் போரில் வென்றபோது","அயோத்தியில் முடிசூடியபோது"],"correctAnswer":1,"explanation":"அயோத்தியா காண்டத்தில் முடிசூட இருந்த இராமனிடம் காட்டிற்குச் செல்ல வேண்டும் என்று கைகேயி கூறியபோது, துளியும் கலங்காமல் இராமனின் முகம் 'அப்பொழுது அலர்ந்த செந்தாமரையினை வென்றது' எனக் கம்பர் இராமனின் மனஉறுதியைச் சிறப்பித்துள்ளார்.","difficulty":"hard","topic":"கம்பராமாயணம்"},{"id":676,"subject":"tamil","testNumber":7,"question":"சேக்கிழார் தாம் இயற்றிய பெரியபுராணத்திற்கு இட்ட பெயர் என்ன? அது சைவத் திருமுறைகளில் எத்தனையாவது திருமுறையாக வைக்கப்பட்டுள்ளது?","options":["திருத்தொண்டர் புராணம் - பன்னிரண்டாம் திருமுறை","திருத்தொண்டத் தொகை - ஏழாம் திருமுறை","திருத்தொண்டர் திருவந்தாதி - பதினோராம் திருமுறை","சிவபுராணம் - எட்டாம் திருமுறை"],"correctAnswer":0,"explanation":"சேக்கிழார் இயற்றிய நூலுக்கு அவரிட்ட பெயர் 'திருத்தொண்டர் புராணம்' ஆகும். இதன் பெருமை கருதி இது 'பெரியபுராணம்' என அழைக்கப்படுகிறது. இது பன்னிரு திருமுறைகளில் 12ஆம் திருமுறையாக அமைந்துள்ளது.","difficulty":"easy","topic":"பெரியபுராணம்"},{"id":677,"subject":"tamil","testNumber":7,"question":"சேக்கிழாரின் இயற்பெயர் மற்றும் அவர் முதலமைச்சராகப் பணியாற்றிய சோழ மன்னன் முறையே யாவர்?","options":["அருண்மொழித்தேவர் - முதலாம் இராசராச சோழன்","அருண்மொழித்தேவர் - இரண்டாம் குலோத்துங்கச் சோழன்","திருமறைக்காடர் - முதலாம் குலோத்துங்கச் சோழன்","வான்மீகி - இராசேந்திர சோழன்"],"correctAnswer":1,"explanation":"குன்றத்தூரில் பிறந்த சேக்கிழாரின் இயற்பெயர் அருண்மொழித்தேவர் ஆகும். இவர் 'அநபாயச் சோழன்' என அழைக்கப்பட்ட இரண்டாம் குலோத்துங்கச் சோழனின் அவையில் முதலமைச்சராகப் பணியாற்றினார்; 'உத்தம சோழப் பல்லவராயர்' என்ற பட்டமும் பெற்றார்.","difficulty":"medium","topic":"பெரியபுராணம்"},{"id":678,"subject":"tamil","testNumber":7,"question":"'பக்திச் சுவை நனி சொட்டச் சொட்டப் பாடிய கவிவலவ' என்று சேக்கிழாரைப் பாராட்டிய தமிழ் அறிஞர் யார்?","options":["உ.வே.சாமிநாதையர்","கவிமணி தேசிக விநாயகம் பிள்ளை","மகாவித்துவான் மீனாட்சிசுந்தரம் பிள்ளை","திரு.வி.கல்யாணசுந்தரனார்"],"correctAnswer":2,"explanation":"சேக்கிழாரின் பக்திப் பெருக்கையும் கவிதைச் சிறப்பையும் போற்றி மகாவித்துவான் மீனாட்சிசுந்தரம் பிள்ளை 'பக்திச் சுவை நனி சொட்டச் சொட்டப் பாடிய கவிவலவ' என்று புகழ்ந்துள்ளார். சேக்கிழார் 'தொண்டர் சீர் பரவுவார்' என்றும் போற்றப்படுகிறார்.","difficulty":"easy","topic":"பெரியபுராணம்"},{"id":679,"subject":"tamil","testNumber":7,"question":"பெரியபுராணம் மொத்தம் எத்தனை சிவனடியார்களின் வரலாற்றையும், எத்தனை சருக்கங்களையும் கொண்டுள்ளது?","options":["63 தனி அடியார்கள் + 9 தொகையடியார்கள் (72 பேர்); 13 சருக்கங்கள்","63 தனி அடியார்கள் + 7 தொகையடியார்கள் (70 பேர்); 12 சருக்கங்கள்","60 தனி அடியார்கள் + 9 தொகையடியார்கள் (69 பேர்); 10 சருக்கங்கள்","72 தனி அடியார்கள் + 9 தொகையடியார்கள் (81 பேர்); 13 சருக்கங்கள்"],"correctAnswer":0,"explanation":"பெரியபுராணம் 63 தனி நாயன்மார்களும் 9 தொகையடியார்களும் ஆக மொத்தம் 72 சிவனடியார்களின் வரலாற்றை 2 காண்டங்கள், 13 சருக்கங்கள் மற்றும் 4,286 பாடல்களில் விரிவாகக் கூறுகிறது.","difficulty":"medium","topic":"பெரியபுராணம்"},{"id":680,"subject":"tamil","testNumber":7,"question":"பெரியபுராணத்திற்கு முதல் நூலாகவும் வழிநூலாகவும் அமைந்தவை முறையே எவை?","options":["திருவாசகம், திருக்கோவையார்","தேவாரம், திருவிசைப்பா","திருமந்திரம், திருத்தொண்டத் தொகை","திருத்தொண்டத் தொகை (சுந்தரர்), திருத்தொண்டர் திருவந்தாதி (நம்பியாண்டார் நம்பி)"],"correctAnswer":3,"explanation":"சுந்தரர் பாடிய 'திருத்தொண்டத் தொகை' முதல் நூலாகவும், அதனை அடியொற்றி நம்பியாண்டார் நம்பி பாடிய 'திருத்தொண்டர் திருவந்தாதி' வழிநூலாகவும் அமைந்தன. அவ்விரு நூல்களையும் அடிப்படையாகக் கொண்டு சேக்கிழார் விரிவாகப் பாடிய சார்பு நூல் பெரியபுராணம் ஆகும்.","difficulty":"hard","topic":"பெரியபுராணம்"},{"id":681,"subject":"tamil","testNumber":7,"question":"'உலகெலாம் உணர்ந்து ஓதற்கரியவன்' எனத் தொடங்கும் பெரியபுராணம் எந்தத் திருத்தலத்தில் அரங்கேற்றப்பட்டது?","options":["மதுரை","திருவாரூர்","தில்லை (சிதம்பரம்)","காஞ்சிபுரம்"],"correctAnswer":2,"explanation":"தில்லை (சிதம்பரம்) நடராசப் பெருமான் 'உலகெலாம்' என்று அடியெடுத்துக் கொடுக்க, சேக்கிழார் பெரியபுராணத்தைப் பாடி தில்லை ஆயிரங்கால் மண்டபத்தில் இரண்டாம் குலோத்துங்கச் சோழன் முன்னிலையில் அரங்கேற்றினார்.","difficulty":"medium","topic":"பெரியபுராணம்"},{"id":682,"subject":"tamil","testNumber":7,"question":"சீறாப்புராணத்தை இயற்றிய உமறுப்புலவர் எவ்வாறு சிறப்பிக்கப்படுகிறார்? இதன் பாட்டுடைத் தலைவன் யார்?","options":["இசுலாமியக் கம்பர் - நபிகள் நாயகம்","கிறிஸ்தவக் கம்பர் - சூசையப்பர்","கவிச்சக்கரவர்த்தி - சீதக்காதி","மகாவித்துவான் - அபுல்காசிம்"],"correctAnswer":0,"explanation":"உமறுப்புலவர் இயற்றிய சீறாப்புராணம் நபிகள் நாயகத்தின் (முகமது நபி) வாழ்க்கை வரலாற்றைக் கூறும் இசுலாமியத் தமிழ்க் காப்பியமாகும். கம்பரைப் போல் காப்பிய நயத்துடன் பாடியதால் உமறுப்புலவர் 'இசுலாமியக் கம்பர்' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"சீறாப்புராணம்"},{"id":683,"subject":"tamil","testNumber":7,"question":"சீறாப்புராணத்தில் அமைந்துள்ள மூன்று காண்டங்களின் சரியான வரிசை எது?","options":["ஹிஜ்ரத்துக் காண்டம், விலாதத்துக் காண்டம், நுபுவ்வத்துக் காண்டம்","நுபுவ்வத்துக் காண்டம், விலாதத்துக் காண்டம், ஹிஜ்ரத்துக் காண்டம்","விலாதத்துக் காண்டம், ஹிஜ்ரத்துக் காண்டம், நுபுவ்வத்துக் காண்டம்","விலாதத்துக் காண்டம், நுபுவ்வத்துக் காண்டம், ஹிஜ்ரத்துக் காண்டம்"],"correctAnswer":3,"explanation":"சீறாப்புராணம் 3 காண்டங்கள், 92 படலங்கள், 5,027 விருத்தப்பாடல்களைக் கொண்டது. அதன் மூன்று காண்டங்கள் முறையே விலாதத்துக் காண்டம் (பிறப்பு), நுபுவ்வத்துக் காண்டம் (நபிப்பட்டம் பெற்றது), ஹிஜ்ரத்துக் காண்டம் (மதினா பயணம்) ஆகும்.","difficulty":"medium","topic":"சீறாப்புராணம்"},{"id":684,"subject":"tamil","testNumber":7,"question":"உமறுப்புலவர் சீறாப்புராணத்தைப் பாடத் தொடங்கியபோது ஆதரித்த வள்ளலும், அவர் மறைந்தபின் நூலை நிறைவு செய்ய உதவிய வள்ளலும் முறையே யாவர்?","options":["சீதக்காதி, அபுல்காசிம் மரைக்காயர்","அபுல்காசிம் மரைக்காயர், சீதக்காதி","சடையப்ப வள்ளல், சீதக்காதி","சீதக்காதி, பனு அகமது மரைக்காயர்"],"correctAnswer":0,"explanation":"வள்ளல் சீதக்காதியின் வேண்டுகோளின்படி உமறுப்புலவர் சீறாப்புராணத்தைப் பாடத் தொடங்கினார். நூல் முடியும் முன்னரே சீதக்காதி இயற்கை எய்தியதால், அபுல்காசிம் மரைக்காயரின் உதவியோடு உமறுப்புலவர் சீறாப்புராணத்தைப் பாடி முடித்தார்.","difficulty":"medium","topic":"சீறாப்புராணம்"},{"id":685,"subject":"tamil","testNumber":7,"question":"உமறுப்புலவரின் ஆசிரியர் யார்? உமறுப்புலவர் இயற்றிய மற்றொரு நூல் எது?","options":["கடிகை முத்துப் புலவர்; முதுமொழி மாலை","படிக்காசுப் புலவர்; சீதக்காதி மாலை","கடிகை முத்துப் புலவர்; சின்னச் சீறா","மீனாட்சிசுந்தரம் பிள்ளை; முதுமொழி மாலை"],"correctAnswer":0,"explanation":"உமறுப்புலவர் எட்டயபுர அரசவைப் புலவரான கடிகை முத்துப் புலவரிடம் தமிழ் கற்றார். சீறாப்புராணம் தவிர இவர் 'முதுமொழி மாலை', 'சீதக்காதி நொண்டி நாடகம்' ஆகிய நூல்களையும் இயற்றியுள்ளார். 'சின்னச் சீறா' பனு அகமது மரைக்காயர் இயற்றியது.","difficulty":"hard","topic":"சீறாப்புராணம்"},{"id":686,"subject":"tamil","testNumber":7,"question":"'சீறாப்புராணம்' என்பதில் 'சீறா' என்னும் அரபுச் சொல்லின் தமிழ் பொருள் என்ன?","options":["புகழ்மாலை","வாழ்க்கை (வாழ்க்கை வரலாறு)","அறநெறி","தூது"],"correctAnswer":1,"explanation":"'சீறா' என்பது 'சீரத்' என்ற அரபுச் சொல்லின் தமிழாக்கமாகும்; இதற்கு 'வாழ்க்கை' என்பது பொருள். 'புராணம்' என்பதற்கு 'வரலாறு' என்பது பொருள். எனவே சீறாப்புராணம் என்பது நபிகள் நாயகத்தின் வாழ்க்கை வரலாற்றைக் கூறும் நூலாகும்.","difficulty":"medium","topic":"சீறாப்புராணம்"},{"id":687,"subject":"tamil","testNumber":7,"question":"வீரமாமுனிவர் இயற்றிய 'தேம்பாவணி' என்னும் கிறிஸ்தவக் காப்பியத்தின் பாட்டுடைத் தலைவன் யார்?","options":["இயேசு கிறிஸ்து","தூய தோமையார்","அருளப்பர்","சூசையப்பர் (வளன்)"],"correctAnswer":3,"explanation":"இத்தாலி நாட்டைச் சேர்ந்த வீரமாமுனிவர் (கான்ஸ்டான்டின் ஜோசப் பெஸ்கி) இயற்றிய தேம்பாவணி, இயேசு கிறிஸ்துவின் வளர்ப்புத் தந்தையான சூசையப்பரை (வளன்) பாட்டுடைத் தலைவனாகக் கொண்டு பாடப்பட்ட கிறிஸ்தவக் காப்பியமாகும்.","difficulty":"easy","topic":"தேம்பாவணி"},{"id":688,"subject":"tamil","testNumber":7,"question":"'தேம்பாவணி' என்ற நூலின் அமைப்பு மற்றும் பெயர்க்காரணம் குறித்த சரியான கூற்று எது?","options":["3 காண்டங்கள், 36 படலங்கள், 3,615 பாடல்கள்; தேம்பா + அணி = வாடாத மாலை","5 பருவங்கள், 47 படலங்கள், 3,766 பாடல்கள்; தேன் + பா + அணி = இனிய மாலை","3 காண்டங்கள், 92 படலங்கள், 5,027 பாடல்கள்; தேம்பா + அணி = வாடாத மாலை","6 காண்டங்கள், 36 படலங்கள், 3,145 பாடல்கள்; தேன் + பா + அணி = வாடாத மாலை"],"correctAnswer":0,"explanation":"தேம்பாவணி 3 காண்டங்களையும், 36 படலங்களையும், 3,615 விருத்தப்பாடல்களையும் கொண்டது. இதன் பெயரை 'தேம்பா + அணி' (வாடாத மாலை) என்றும், 'தேன் + பா + அணி' (தேன் போன்ற இனிய பாடல்களின் மாலை) என்றும் இருவகையாகப் பிரித்துப் பொருள் கொள்வர்.","difficulty":"medium","topic":"தேம்பாவணி"},{"id":689,"subject":"tamil","testNumber":7,"question":"வீரமாமுனிவரின் இயற்பெயர் என்ன? அவர் இயற்றிய தமிழின் முதல் அகராதி எது?","options":["ஜி.யு.போப்; திருவாசக அகராதி","ராபர்ட் கால்டுவெல்; திராவிட அகராதி","கான்ஸ்டான்டின் ஜோசப் பெஸ்கி; சதுரகராதி","சீகன்பால்கு; தமிழ்-இலத்தீன் அகராதி"],"correctAnswer":2,"explanation":"வீரமாமுனிவரின் இயற்பெயர் கான்ஸ்டான்டின் ஜோசப் பெஸ்கி (Constantine Joseph Beschi) ஆகும். இவர் தேம்பாவணி மட்டுமின்றி தமிழின் முதல் அகராதியான 'சதுரகராதி', 'பரமார்த்த குரு கதை', 'தொன்னூல் விளக்கம்' முதலிய நூல்களையும் இயற்றியுள்ளார்.","difficulty":"easy","topic":"தேம்பாவணி"},{"id":690,"subject":"tamil","testNumber":7,"question":"வீரமாமுனிவர் தமது தேம்பாவணியில் 'திருமுழுக்கு யோவான்' (அருளப்பர்) அவர்களுக்கு இட்ட தூய தமிழ்ப் பெயர் என்ன?","options":["கருணையன்","வளன்","மரியாள்","அருளன்"],"correctAnswer":0,"explanation":"வீரமாமுனிவர் தேம்பாவணியில் விவிலியப் பெயர்களை இனிய தமிழ்ப் பெயர்களாக மாற்றிப் பாடினார். அதன்படி சூசையப்பருக்கு 'வளன்' என்றும், திருமுழுக்கு யோவானுக்கு 'கருணையன்' என்றும் பெயரிட்டார். சமச்சீர் பத்தாம் வகுப்புத் தமிழில் கருணையன் தன் தாய் எலிசபெத் மறைந்ததற்காகப் புலம்பும் பகுதி இடம்பெற்றுள்ளது.","difficulty":"hard","topic":"தேம்பாவணி"},{"id":691,"subject":"tamil","testNumber":7,"question":"'கிறிஸ்தவக் கம்பர்' என்று போற்றப்படும் எச்.ஏ.கிருட்டிணப்பிள்ளை இயற்றிய காப்பியம் எது?","options":["தேம்பாவணி","இயேசு காவியம்","பெத்லகேம் குறவஞ்சி","இரட்சணிய யாத்திரிகம்"],"correctAnswer":3,"explanation":"திருநெல்வேலி மாவட்டம் கரையிருப்பில் பிறந்த ஹென்றி ஆல்பிரட் கிருட்டிணப்பிள்ளை (எச்.ஏ.கிருட்டிணப்பிள்ளை) 'இரட்சணிய யாத்திரிகம்' என்னும் காப்பியத்தை இயற்றினார். கம்பராமாயண நடையைத் தழுவிப் பாடியதால் இவர் 'கிறிஸ்தவக் கம்பர்' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"இரட்சணிய யாத்திரிகம்"},{"id":692,"subject":"tamil","testNumber":7,"question":"எச்.ஏ.கிருட்டிணப்பிள்ளையின் 'இரட்சணிய யாத்திரிகம்' எந்த ஆங்கில நூலைத் தழுவி எழுதப்பட்டது?","options":["ஜான் மில்டன் எழுதிய 'பாரடைஸ் லாஸ்ட்'","ஜான் பன்யன் எழுதிய 'பில்கிரிம்ஸ் புரோகிரஸ்'","வில்லியம் ஷேக்ஸ்பியர் எழுதிய 'டெம்பெஸ்ட்'","லார்ட் டென்னிசன் எழுதிய 'இன் மெமோரியம்'"],"correctAnswer":1,"explanation":"இரட்சணிய யாத்திரிகம் ஜான் பன்யன் (John Bunyan) ஆங்கிலத்தில் இயற்றிய 'பில்கிரிம்ஸ் புரோகிரஸ்' (Pilgrim's Progress - திருப்பயணியின் முன்னேற்றம்) என்ற உருவக நூலைத் தழுவித் தமிழ்க் காப்பிய மரபில் இயற்றப்பட்டதாகும்.","difficulty":"medium","topic":"இரட்சணிய யாத்திரிகம்"},{"id":693,"subject":"tamil","testNumber":7,"question":"இரட்சணிய யாத்திரிகத்தின் அமைப்பு குறித்த சரியான விவரம் எது?","options":["5 பருவங்கள், 47 படலங்கள், 3,766 பாடல்கள்","3 காண்டங்கள், 36 படலங்கள், 3,615 பாடல்கள்","10 பருவங்கள், 47 படலங்கள், 4,351 பாடல்கள்","5 பருவங்கள், 30 படலங்கள், 2,500 பாடல்கள்"],"correctAnswer":0,"explanation":"இரட்சணிய யாத்திரிகம் ஆதி பருவம், குமார பருவம், நிதான பருவம், ஆரணிய பருவம், இரட்சணிய பருவம் ஆகிய 5 பருவங்களையும், 47 படலங்களையும், 3,766 பாடல்களையும் கொண்டுள்ளது.","difficulty":"hard","topic":"இரட்சணிய யாத்திரிகம்"},{"id":694,"subject":"tamil","testNumber":7,"question":"'வில்லிபாரதம்' என்னும் காப்பியத்தை இயற்றிய வில்லிபுத்தூராரை ஆதரித்த வள்ளல் யார்?","options":["சடையப்ப வள்ளல்","சந்திரன் சுவர்க்கி","வக்கபாகை வரபதி ஆட்கொண்டான்","வள்ளல் சீதக்காதி"],"correctAnswer":2,"explanation":"கி.பி. 14ஆம் நூற்றாண்டைச் சேர்ந்த வில்லிபுத்தூரார் திருமுனைப்பாடி நாட்டின் சனியூரில் பிறந்தவர். இவரை ஆதரித்து வில்லிபாரதம் பாடச் செய்தவர் வக்கபாகை அரசர் வரபதி ஆட்கொண்டான் ஆவார்.","difficulty":"medium","topic":"வில்லிபாரதம்"},{"id":695,"subject":"tamil","testNumber":7,"question":"வியாசரின் வடமொழி மகாபாரதத்தில் உள்ள 18 பருவங்களில், வில்லிபுத்தூரார் தமது வில்லிபாரதத்தில் எத்தனை பருவங்களை மட்டும் பாடினார்?","options":["8 பருவங்கள்","12 பருவங்கள்","18 பருவங்கள்","10 பருவங்கள்"],"correctAnswer":3,"explanation":"வில்லிபுத்தூரார் வியாச பாரதத்தின் முதல் 10 பருவங்களை மட்டுமே (ஆதிபருவம் முதல் சௌப்திக பருவம் வரை) 4,351 விருத்தப்பாடல்களில் பாடினார். எஞ்சிய 8 பருவங்களைப் பிற்காலத்தில் அட்டாவதானம் அரங்கநாத கவிராயர் பாடி நிறைவு செய்தார்.","difficulty":"medium","topic":"வில்லிபாரதம்"},{"id":696,"subject":"tamil","testNumber":7,"question":"வில்லிபாரதத்தில் 'கிருஷ்ணன் தூதுச் சருக்கம்' எந்தப் பருவத்தில் இடம்பெற்றுள்ளது?","options":["ஆதி பருவம்","சபா பருவம்","விராட பருவம்","உத்தியோக பருவம்"],"correctAnswer":3,"explanation":"வில்லிபாரதத்தின் ஐந்தாவது பருவமான 'உத்தியோக பருவத்தில்', பாண்டவர்களுக்காகக் கண்ணன் கௌரவர்களிடம் சமாதானத் தூது செல்லும் 'கிருஷ்ணன் தூதுச் சருக்கம்' மிகச் சிறந்த இலக்கிய நயத்துடன் அமைந்துள்ளது.","difficulty":"hard","topic":"வில்லிபாரதம்"},{"id":697,"subject":"tamil","testNumber":7,"question":"'வெண்பாவிற் புகழேந்தி' எனப் போற்றப்படும் புகழேந்திப் புலவர் இயற்றிய 'நளவெண்பா' எத்தனை காண்டங்களைக் கொண்டது?","options":["3 காண்டங்கள் (சுயம்வர, கலிதொடர், கலிநீங்கு காண்டம்)","5 காண்டங்கள்","6 காண்டங்கள்","2 காண்டங்கள் (சுயம்வர, கலிநீங்கு காண்டம்)"],"correctAnswer":0,"explanation":"பொன்விளைந்த களத்தூரில் பிறந்த புகழேந்திப் புலவர் இயற்றிய நளவெண்பா, சுயம்வர காண்டம், கலிதொடர் காண்டம், கலிநீங்கு காண்டம் ஆகிய 3 காண்டங்களைக் கொண்டது. நிடத நாட்டு மன்னன் நளன் மற்றும் தமயந்தியின் வரலாற்றை இனிய வெண்பாக்களில் கூறுகிறது.","difficulty":"medium","topic":"நளவெண்பா"},{"id":698,"subject":"tamil","testNumber":7,"question":"நளவெண்பா இயற்றிய புகழேந்திப் புலவரை ஆதரித்த முள்ளூர் மன்னன் யார்?","options":["வரபதி ஆட்கொண்டான்","சந்திரன் சுவர்க்கி","சடையப்ப வள்ளல்","இரண்டாம் குலோத்துங்கன்"],"correctAnswer":1,"explanation":"புகழேந்திப் புலவரை ஆதரித்த வள்ளல் முள்ளூர் (மழவ நாட்டு முள்ளூர்) மன்னன் சந்திரன் சுவர்க்கி ஆவார். புகழேந்திப் புலவர் தமது நளவெண்பாவில் சந்திரன் சுவர்க்கியை நன்றியோடு சிறப்பித்துப் பாடியுள்ளார்.","difficulty":"medium","topic":"நளவெண்பா"},{"id":699,"subject":"tamil","testNumber":7,"question":"'கொங்குவேள் மாக்கதை' என்று அழைக்கப்படும் 'பெருங்கதை' என்ற சமணக் காப்பியத்தை இயற்றியவர் யார்? இதன் பாட்டுடைத் தலைவன் யார்?","options":["தோலாமொழித்தேவர் - திவிட்டன்","திருத்தக்கதேவர் - சீவகன்","கொங்குவேளிர் - உதயணன்","வெண்ணாவலுடையார் வேள் - யசோதரன்"],"correctAnswer":2,"explanation":"கொங்கு நாட்டு விசயமங்கலத்தைச் சேர்ந்த சமணப் புலவரான கொங்குவேளிர் 'பெருங்கதை' என்ற காப்பியத்தை இயற்றினார். இதன் பாட்டுடைத் தலைவன் வத்தவ நாட்டு மன்னன் உதயணன் ஆவார்; எனவே இது 'உதியணன் கதை' என்றும் அழைக்கப்படுகிறது.","difficulty":"medium","topic":"பெருங்கதை"},{"id":700,"subject":"tamil","testNumber":7,"question":"கொங்குவேளிரின் 'பெருங்கதை' எந்த மொழியிலிருந்த 'பிருகத்கதா' என்ற நூலைத் தழுவி எந்தப் பா வகையில் இயற்றப்பட்டது?","options":["பைசாச மொழி (குணாட்டியர்) - அகவற்பா (ஆசிரியப்பா)","பாலி மொழி - விருத்தப்பா","வடமொழி (வியாசர்) - வெண்பா","பிராகிருத மொழி - கலிப்பா"],"correctAnswer":0,"explanation":"குணாட்டியர் பைசாச மொழியில் எழுதிய 'பிருகத்கதா' என்னும் பெருங்கதை நூலைத் தழுவிக் கொங்குவேளிர் அகவற்பாவில் (ஆசிரியப்பா) 'பெருங்கதை'யை இயற்றினார். இந்நூலை 1924ஆம் ஆண்டு தமிழ்த்தாத்தா உ.வே.சாமிநாதையர் பதிப்பித்து வெளியிட்டார்.","difficulty":"hard","topic":"பெருங்கதை"}]);
